package com.chami.pdfmaker.ui

// Press Start 2P pixel font (OFL, google/fonts) embedded as Base64.
// The TTF is binary and cannot be pushed through the GitHub contents
// API, so the font ships as text and is decoded at runtime into a
// Typeface (see DesignSystem.buildPixelFontFamily).
// Source: https://github.com/google/fonts/raw/main/ofl/pressstart2p/PressStart2P-Regular.ttf
internal object PixelFontData {
  // Each chunk is under the 64 KB string-constant limit.
  val chunks: Array<String> = arrayOf(
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
  )

  val base64: String get() = (chunks + PixelFontDataPart2.chunks).joinToString("")
}
